/**
 * EdgeOne Makers Node.js Cloud Functions entry point.
 *
 * Deployed as file-routed functions under `cloud-functions/**` (generated by
 * scripts/build-edgeone.mjs from this module). The backend namespaces served
 * here are exactly the ones `isBackendRequestPath` recognizes; everything
 * else (the web vault) is served as EdgeOne static assets from `dist/`.
 *
 * Platform wiring:
 * - Data: MySQL via `src/platform/mysql` (`MYSQL_URI` / `DATABASE_URL`).
 * - Realtime push: degraded mode (no Durable Objects) — clients fall back to
 *   revision-date polling; signed connection tickets still work.
 * - Remote backup transfer: degraded mode (503) until a queued replacement
 *   exists.
 * - Attachment / send blob storage: requires a platform blob adapter
 *   (EdgeOne Blob) — not wired yet, endpoints degrade gracefully.
 */
import type { Env } from './types';
import { createMysqlDatabase } from './platform/mysql/mysql-database';
import { createEdgeOneBlobBackend } from './platform/edgeone/attachments';
import { StorageService } from './services/storage';
import { applyCors, jsonResponse } from './utils/response';
import { handleRequest } from './router';
import { isBackendRequestPath, webVaultNotFoundResponse } from './web-vault-visibility';

export interface EdgeOneFunctionContext {
  request: Request;
  params?: Record<string, string | string[] | undefined>;
  env?: Record<string, unknown>;
  waitUntil?: (promise: Promise<unknown>) => void;
}

function normalizeRequestUrl(request: Request): Request {
  const url = new URL(request.url);
  const normalizedPathname = url.pathname.length <= 1 ? url.pathname : url.pathname.replace(/\/+$/, '');
  if (normalizedPathname === url.pathname) return request;
  url.pathname = normalizedPathname;
  return new Request(url.toString(), request);
}

// The EdgeOne Node runtime provides globals without @types/node in this repo.
declare const process: { readonly env?: Record<string, string | undefined> };

function readVar(context: EdgeOneFunctionContext, key: string): string | undefined {
  const fromContext = context.env?.[key];
  if (typeof fromContext === 'string' && fromContext.trim() !== '') return fromContext.trim();
  const fromProcess = process.env?.[key];
  return typeof fromProcess === 'string' && fromProcess.trim() !== '' ? fromProcess.trim() : undefined;
}

/** Builds the NodeWarden `Env` for the EdgeOne Node.js runtime, or null with a config error. */
export function createEdgeOneEnv(
  context: EdgeOneFunctionContext
): { env: Env } | { env: null; error: string } {
  const mysqlUri = readVar(context, 'MYSQL_URI') || readVar(context, 'DATABASE_URL');
  if (!mysqlUri) {
    return { env: null, error: 'MYSQL_URI (or DATABASE_URL) is not configured' };
  }
  const jwtSecret = readVar(context, 'JWT_SECRET');
  if (!jwtSecret) {
    return { env: null, error: 'JWT_SECRET is not configured' };
  }
  const env: Env = {
    DB: createMysqlDatabase({ connectionUri: mysqlUri }),
    JWT_SECRET: jwtSecret,
  } as unknown as Env;

  // Attachment / send-file storage via EdgeOne Blob (opt-out with the
  // namespace variable set to 'off'); blob-store still prefers R2/KV when
  // those bindings exist so this stays a no-op on Cloudflare.
  const blobNamespace = readVar(context, 'ATTACHMENTS_BLOB_NAMESPACE') || 'nodewarden-attachments';
  if (blobNamespace.toLowerCase() !== 'off') {
    env.ATTACHMENTS_BLOB = createEdgeOneBlobBackend(blobNamespace);
  }

  const optionalVariables: Array<[string, string]> = [
    ['INTERNAL_ACCESS_TOKEN', 'INTERNAL_ACCESS_TOKEN'],
    ['WEBAUTHN_RP_ID', 'WEBAUTHN_RP_ID'],
    ['WEBAUTHN_RP_NAME', 'WEBAUTHN_RP_NAME'],
    ['WEBAUTHN_ALLOWED_ORIGINS', 'WEBAUTHN_ALLOWED_ORIGINS'],
    ['YUBICO_VALIDATION_URLS', 'YUBICO_VALIDATION_URLS'],
    ['HIDE_WEB_VAULT', 'HIDE_WEB_VAULT'],
  ];
  for (const [key, variable] of optionalVariables) {
    const value = readVar(context, variable);
    if (value !== undefined) (env as unknown as Record<string, unknown>)[key] = value;
  }
  return { env };
}

// mirrors src/index.ts: schema bootstrap runs once per Node isolate
let dbInitialized = false;
let dbInitError: string | null = null;
let dbInitPromise: Promise<void> | null = null;

async function ensureDatabaseInitialized(env: Env): Promise<void> {
  if (dbInitialized) return;
  if (!dbInitPromise) {
    dbInitPromise = (async () => {
      const storage = new StorageService(env.DB);
      await storage.initializeDatabase();
      dbInitialized = true;
      dbInitError = null;
    })()
      .catch((error: unknown) => {
        console.error('Failed to initialize database:', error);
        dbInitError = error instanceof Error ? error.message : 'Unknown database initialization error';
      })
      .finally(() => {
        dbInitPromise = null;
      });
  }
  await dbInitPromise;
}

function configurationErrorResponse(error: string): Response {
  console.error('EdgeOne configuration error (not forwarded):', error);
  return jsonResponse(
    {
      error: 'Server configuration incomplete',
      error_description: 'Required environment variables are missing. Check server logs for details.',
      ErrorModel: {
        Message: 'Service temporarily unavailable',
        Object: 'error',
      },
    },
    503
  );
}

function defaultCorsEnv(): Env {
  // applyCors only reads optional configuration (allowed origins); a bare
  // Env is fine for error paths that happen before configuration resolves.
  return { DB: null, JWT_SECRET: '' } as unknown as Env;
}

export async function handleEdgeOneRequest(
  context: EdgeOneFunctionContext,
  overrides?: Partial<Env>
): Promise<Response> {
  const request = normalizeRequestUrl(context.request);
  const pathname = new URL(request.url).pathname;
  if (!isBackendRequestPath(pathname)) {
    // Static platform assets (dist/) answer every other path; this function
    // was probably invoked via a stale route, answer uniformly.
    return applyCors(request, webVaultNotFoundResponse(request), defaultCorsEnv());
  }

  const resolved = createEdgeOneEnv(context);
  if (!resolved.env) {
    return applyCors(request, configurationErrorResponse(resolved.error), defaultCorsEnv());
  }
  const env = resolved.env;
  if (overrides) Object.assign(env as unknown as Record<string, unknown>, overrides);

  await ensureDatabaseInitialized(env);
  if (dbInitError) {
    const resp = jsonResponse(
      {
        error: 'Database not initialized',
        error_description: 'Database initialization failed. Check server logs for details.',
        ErrorModel: {
          Message: 'Service temporarily unavailable',
          Object: 'error',
        },
      },
      503
    );
    return applyCors(request, resp, env);
  }

  const resp = await handleRequest(request, env);
  return applyCors(request, resp, env);
}

/** EdgeOne Node.js Cloud Functions entry (`export default onRequest(context)`). */
export default async function onRequest(context: EdgeOneFunctionContext): Promise<Response> {
  try {
    return await handleEdgeOneRequest(context);
  } catch (error) {
    console.error('Unhandled request failure:', error);
    return jsonResponse(
      {
        error: 'Unhandled error',
        error_description: 'The request failed unexpectedly. Check server logs for details.',
        ErrorModel: {
          Message: 'Service temporarily unavailable',
          Object: 'error',
        },
      },
      500
    );
  }
}
